-- Additive source metadata. Existing documents, users and moderation data are untouched.
alter table public.country_documents
 add column if not exists visa_type text,
 add column if not exists sort_order integer,
 add column if not exists requirement text not null default 'required' check(requirement in ('required','conditional','recommended')),
 add column if not exists source_name text,
 add column if not exists source_document text,
 add column if not exists source_type text,
 add column if not exists source_scope text,
 add column if not exists source_updated_at date,
 add column if not exists editor_note text,
 add column if not exists details jsonb not null default '[]'::jsonb;
create index if not exists country_documents_order_idx on public.country_documents(country_id,visa_type,sort_order);
-- Source publication/update dates are unknown and deliberately NULL.
insert into public.country_documents (id,country_id,title,body,category,source_url,visa_type,sort_order,requirement,source_name,source_document,source_type,source_scope,source_updated_at,editor_note,details)
select id,country_id,title,body,category,source_url,visa_type,sort_order,requirement,source_name,source_document,source_type,source_scope,source_updated_at,editor_note,details from jsonb_to_recordset($spain$[{"id": "1de9d862-d2e3-5be5-b46a-9ebb4c15f00a", "country_id": "spain", "title": "Pasaport", "body": "Planlanan seyahatin dönüş tarihinden itibaren en az 3 ay daha geçerli olmalı; en az 2 karşılıklı boş sayfası bulunmalıdır. Evlilik nedeniyle soyadı değişmişse pasaportta evlilik sonrası güncel soyadı bulunmalıdır.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 1, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "eaf68fb1-bce4-55b8-96fb-a7f152ecee84", "country_id": "spain", "title": "Biyometrik fotoğraf", "body": "2 adet fotoğraf istenir; biri Schengen başvuru formuna yapıştırılır. Son 6 ay içinde çekilmiş, 35 × 45 mm ölçülerinde ve gözlük gibi aksesuarlar olmadan hazırlanmalıdır. Ölçülere uymayan fotoğraflar kabul edilmez. Kaynak, ihtiyaç halinde başvuru merkezinde fotoğraf hizmeti satın alınabileceğini belirtir; ücret bilgisi vermez.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 2, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "76453d6e-cb0d-577c-b5d1-e48f660e3524", "country_id": "spain", "title": "Ulaşım rezervasyonları", "body": "Uçak rezervasyonu, başvuru gününden en az 15 gün sonraki seyahat için düzenlenmelidir. Ara geçişler varsa uçak, tren vb. rezervasyonlar da sunulmalıdır. Birden fazla Schengen ülkesi ziyaret ediliyorsa en uzun kalış İspanya’da olmalıdır; eşit süreli kalışlar varsa ilk giriş İspanya olmalıdır.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 3, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "cfa76a69-c1f6-5a44-b6c5-cb13a910bfc6", "country_id": "spain", "title": "Konaklama belgeleri", "body": "Otel rezervasyonu seyahatin tamamını kapsamalı, eksik gün olmamalıdır. Kendi evinde kalacak kişi tapu sunmalıdır. Başkasının evinde kalınacaksa ev sahibinin İspanya polisinden aldığı sarı davetiye ya da kira sözleşmesi istenir. Kaynak Airbnb için de kira sözleşmesinden (AirB&B sözleşmesi) bahseder.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 4, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "76da0ec2-95c4-52ef-9df2-074e0a6f5244", "country_id": "spain", "title": "Yurtdışı seyahat sağlık sigortası", "body": "Sigorta seyahatten 1 gün önce başlayacak şekilde düzenlenmeli, seyahatin tamamını kapsamalı, en az 30.000 € teminatlı ve Schengen Bölgesi’nde geçerli olmalıdır. 7 günden kısa seyahatler için en az 7 günlük sigorta sunulmalıdır. Kaynak PDF sigortanın ıslak imzalı veya kaşeli olmasını şart koşmaz.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 5, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "b71a51a7-a5ca-5f76-900c-9fc33ce93c66", "country_id": "spain", "title": "Seyahat amacı / niyet dilekçesi", "body": "Seyahat nedenini açıklayan İspanyolca niyet dilekçesi sunulmalıdır.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 6, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "9f567d1f-c738-501a-bcd4-0a3ca62c9772", "country_id": "spain", "title": "Çalışma veya gelir durumunu açıklayan belgeler", "body": "Durumuna uygun alt listeyi incele. Ana evrak sırası değişmez; bu seçim belge muafiyeti veya uygunluk kararı değildir.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 7, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": [{"title": "A. Çalışanlar", "applies_to": ["employee"], "items": ["İşverenin yazdığı, imzaladığı ve kaşelediği; seyahat tarihlerini açıkça belirten İspanyolca işveren mektubu.", "e-Devlet’ten alınmış QR kodlu işe giriş bildirgesi.", "e-Devlet’ten alınmış QR kodlu SGK hizmet dökümü.", "Son 3 aya ait, işyerinin imzaladığı ve kaşelediği maaş bordrosu.", "İşyerinin faaliyet belgesi.", "İşyerinin Resmî Gazete kaydı ve imza sirküleri.", "Vergi levhası."]}, {"title": "B. İşveren / şirket sahipleri", "applies_to": ["owner"], "items": ["Şirket ortaklığı varsa şirket ortağının yazdığı, imzaladığı ve kaşelediği; seyahat tarihlerini ve ortaklık durumunu gösteren İspanyolca dilekçe. Şirketin %100 sahibi veya tüzel kişi olunması durumunda kişinin kendisinin yazdığı, imzaladığı ve kaşelediği; seyahat tarihlerini ve şirket sahipliğini gösteren İspanyolca dilekçe.", "e-Devlet’ten alınmış QR kodlu SGK hizmet dökümü.", "Son 3 aya ait, işyerinin imzaladığı ve kaşelediği maaş bordrosu.", "İşyerinin faaliyet belgesi.", "İşyerinin Resmî Gazete kaydı ve imza sirküleri.", "Vergi levhası."]}, {"title": "C. Emekliler", "applies_to": ["retired"], "items": ["e-Devlet’ten alınmış QR kodlu emeklilik belgesi."]}, {"title": "D. Çalışmayanlar ve öğrenciler", "applies_to": ["unemployed", "student"], "items": ["Sponsor sunulması zorunludur; kaynağa göre sponsor yalnız anne, baba veya eş olabilir.", "Sponsor, masrafları karşılamayı kabul ettiğini beyan eden dilekçe ve çalışma durumuna uygun yukarıdaki destekleyici evrakları sunmalıdır.", "Başvuru sahibinin e-Devlet’ten alınmış QR kodlu SGK hizmet dökümü sunulmalıdır.", "Başvuru sahibi öğrenciyse ayrıca öğrenci belgesi sunulmalıdır."]}]}, {"id": "7a3828b6-2236-55a7-9f1e-8b829cd0eaf7", "country_id": "spain", "title": "Maddi durumu gösteren belgeler", "body": "TL, Euro veya Dolar cinsinden vadesiz banka hesabına ait son 6 aylık hesap hareketleri sunulmalıdır. Hesap hareketleri başvuru gününden en geç 1 hafta önce alınmış olmalıdır. Kaynak, ulaşım ve konaklama masraflarına ek olarak günlük 150 € hesaplanmasını ister: 7 gün × 150 € = 1.050 € + uçak + otel. Altın, vadeli mevduat ve fon hesaplarının dikkate alınmadığı belirtilir.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 8, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": [{"title": "Zorunlu hesap dökümü", "applies_to": [], "items": ["Kaynağa göre banka imza sirküleri sunmaya gerek yoktur."]}, {"title": "Tavsiye ve ek belgeler", "applies_to": [], "requirement": "recommended", "items": ["Kaynak bankada en az 1.500–2.000 € gösterilmesini tavsiye eder; bu tutar herkes için kesin bir asgari zorunluluk değildir.", "QR kodlu vadesiz banka hesap özeti sunulması tavsiye edilir.", "Ek olarak tapu ve araç ruhsatı sunulabilir."]}]}, {"id": "bbd567d1-7364-5af6-94ed-517a16f5891c", "country_id": "spain", "title": "Vukuatlı nüfus kayıt örneği", "body": "e-Devlet üzerinden “Nüfus / Aile” seçeneğiyle alınmış vukuatlı nüfus kayıt örneği.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 9, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "e0d07f2a-f7ea-5898-a05b-94d8800daa54", "country_id": "spain", "title": "Tarihçeli yerleşim yeri belgesi", "body": "e-Devlet üzerinden alınmış tarihçeli yerleşim yeri belgesi. Kaynak bu belgeyi ikametgâh belgesinden ayrı bir madde olarak ister.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 10, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "6c5f6618-0502-5f96-b953-c76f0439a80f", "country_id": "spain", "title": "İkametgâh belgesi", "body": "e-Devlet üzerinden alınmış ikametgâh (yerleşim yeri) belgesi. 10. maddeyle birleştirilmez; kaynakta ayrı istenir.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 11, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "9c339ae7-4834-583c-9797-454ba6b6f776", "country_id": "spain", "title": "18 yaş altı başvuruları", "body": "Bu madde yalnız 18 yaşından küçük başvuru sahiplerine uygulanır. Özel koşulları aşağıdan kontrol et.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 12, "requirement": "conditional", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": [{"title": "Doğum kaydı ve dil", "applies_to": [], "items": ["e-Devlet’ten alınmış Formül A veya doğum belgesi sunulur. e-Devlet’ten İspanyolca dahil çok dilli alınabilir; başka dildeyse yeminli tercümanın İspanyolca çevirisi gerekir."]}, {"title": "Muvafakatname, tercüme ve apostil", "applies_to": [], "items": ["Çocuk anne ve babasıyla birlikte seyahat etmiyorsa birlikte gideceği kişiye yönelik noter muvafakatnamesi gerekir. Anne ve baba noter huzurunda çocuğun “İspanya ülkesine, … ile birlikte gitmesine” ifadesinin kesinlikle geçtiği beyanı vermelidir.", "Muvafakatnamenin yeminli tercüman tarafından İspanyolcaya çevrilmiş ve apostil edilmiş Türkçe ve İspanyolca orijinalleri ile “ASLI GİBİDİR” kopyaları sunulmalıdır."]}, {"title": "Tek ebeveyn, vefat ve mahkeme kararı", "applies_to": [], "items": ["Çocuk yalnız annesiyle gidiyorsa baba anneye; yalnız babasıyla gidiyorsa anne babaya muvafakat vermelidir.", "Anne veya babadan biri vefat etmişse e-Devlet’ten alınmış çok dilli Formül C belgesi sunulur.", "Kaynak, yasal ebeveynlerin mahkeme kararıyla değiştiği durum için mahkeme kararının yeminli tercüman tarafından İspanyolca çevirisini, orijinalini ve “ASLI GİBİDİR” kopyasını ister. Duruma özel uygulamayı başvuru merkezinden teyit et."]}]}, {"id": "0da4d6a5-34f1-5b1d-a199-5e5a9feb0698", "country_id": "spain", "title": "Pasaport ve kimlik fotokopileri", "body": "Kimlik ve pasaport fotokopileri; mevcut pasaportun ön yüzü, Schengen vizeleri ve damgalı sayfaları sunulmalıdır. Varsa önceki pasaportlardaki Schengen vizeleri ve giriş-çıkış damgaları da eklenmelidir.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 13, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}]$spain$::jsonb) as d(id uuid,country_id text,title text,body text,category text,source_url text,visa_type text,sort_order integer,requirement text,source_name text,source_document text,source_type text,source_scope text,source_updated_at date,editor_note text,details jsonb)
on conflict(id) do nothing;
-- Preserve every existing record. Only valid completed application dates enter aggregate stats.
create or replace function public.country_stats(target_country text) returns table(experiences bigint,questions bigint,tips bigint,average_days numeric,recent bigint) language sql stable security invoker set search_path='' as $$
 select count(*) filter(where kind='experience'),count(*) filter(where kind='question'),count(*) filter(where kind='tip'),round(avg(decision_date-application_date) filter(where kind='experience' and application_date>='1985-01-01'::date and decision_date>=application_date and decision_date<=current_date)),count(*) filter(where created_at>now()-interval '7 days') from public.posts where country_id=target_country and status='approved'
$$;
